	["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158}, {area:16723} kasabasından çıkmak istiyor: onu batıya, kasabanın kenarındaki hazinesine götür ve tarikatçıları ondan uzak tut.",
	-- {npc:259158} Fuzzle · {area:16723} Sunnyglade
	["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "{npc:259158} yaratığını {area:16723} kasabasından, kasabanın batısındaki hazinesine götür",

	-- Step 43: Tran'gul
	-- {area:16743} Rog'mar
	["East back to {area:16743}."] = "Doğuya, {area:16743} kalesine dön.",
	-- {quest:94727} Digging for Answers · {npc:260931} Clubtoe · {area:16723} Sunnyglade
	["{quest:94727}: for {npc:260931} in {area:16723}"] = "{quest:94727}: {area:16723} köyündeki {npc:260931} için",

	-- Step 44: Clubtoe
	-- {area:16723} Sunnyglade · {npc:260931} Clubtoe · {npc:256710} Tran'gul
	["West to {area:16723} again: {npc:260931}, a Twilight miner who wants out, waits at the town's eastern edge. Talk him round, then hand {npc:256710}'s quest in; one of the missing ogres stands a few steps west."] = "Yine batıya, {area:16723} köyüne git: kaçmak isteyen bir Twilight madencisi olan {npc:260931} kasabanın doğu kenarında bekliyor. Onu ikna et, sonra {npc:256710} adlı NPC'nin görevini teslim et; kayıp ogre'lerden biri birkaç adım batıda duruyor.",
	-- {npc:260931} Clubtoe
	["talk {npc:260931} round"] = "{npc:260931} adlı NPC'yi ikna et",
	-- {npc:261208} Twilight Brute
	["{npc:261208}, a few steps west"] = "{npc:261208}, birkaç adım batıda",

	-- Step 45: The ritual grounds
	["The ritual grounds"] = "Ayin alanı",
	-- {area:16723} Sunnyglade · {npc:256899} Chogg'Zac
	["The ritualists and their empowered brutes gather at the ritual circles in the middle of {area:16723}: wreck five of the circles.\nCareful: {npc:256899}, the elite ogre (level 41), walks through here from the western streets: watch for him before each pull."] = "Ayincilar ve güçlendirilmiş kaba kuvvetleri {area:16723} köyünün ortasındaki ayin çemberlerinde toplanıyor: çemberlerden beşini boz.\nDikkat: elit ogre {npc:256899} (41. seviye) batı sokaklarından buradan geçer: her çekişten önce onu gözle.",
	-- plural, as words: Twilight Ritual Circles = {npc:262006} Twilight Ritual Circle
	["destroy 5 Twilight Ritual Circles"] = "5 Twilight Ritual Circle yok et",

	-- Step 47: Chogg'Zac
	-- {npc:256899} Chogg'Zac · {area:16723} Sunnyglade · {npc:255829} Clugfist · {area:16726} Bolder'ok · {quest:95420} Land of Giants · {npc:258570} Da'grosh
	["Careful: {npc:256899}, the two-headed ogre at the western edge of {area:16723}, is an elite (level 41): grouping up is advised under 43. Clear the cultists around him first and come in with full health and mana: recorded players of 42-43 killed him alone. {npc:255829}'s quests in {area:16726} wait on this one: skip him and {quest:95420}, the {area:16726} quests and {npc:258570}'s camp in the west go with him (about 21,000 XP); the guide then leaves them out."] = "Dikkat: {area:16723} köyünün batı kenarındaki iki başlı ogre {npc:256899} bir elit (41. seviye): 43'ün altındaysan grup kurman tavsiye edilir. Önce çevresindeki tarikatçıları temizle ve tam can ve manayla gir: kaydedilen 42-43 seviyesindeki oyuncular onu tek başına öldürdü. {npc:255829} adlı NPC'nin {area:16726} kasabasındaki görevleri buna bağlı: onu atlarsan {quest:95420}, {area:16726} görevleri ve batıdaki {npc:258570} kampı da onunla gider (yaklaşık 21.000 XP); rehber de bunları dışarıda bırakır.",

	-- Step 48: Clubtoe
	-- {quest:95418} Spread the Word · {npc:256710} Tran'gul · {area:16743} Rog'mar
	["{quest:95418}: for {npc:256710} in {area:16743}"] = "{quest:95418}: {area:16743} kalesindeki {npc:256710} için",

	-- Step 49: Tran'gul
	-- {area:16743} Rog'mar · {npc:260931} Clubtoe · {npc:256710} Tran'gul · {npc:255829} Clugfist
	["East back to {area:16743}: {npc:260931}'s word goes to {npc:256710}, and {npc:256710}'s to {npc:255829}, the ogres' chieftain."] = "Doğuya, {area:16743} kalesine dön: {npc:260931} adlı NPC'nin haberi {npc:256710} için, {npc:256710} adlı NPC'ninki de ogre'lerin şefi {npc:255829} için.",
	-- {quest:95420} Land of Giants · {npc:255829} Clugfist · {area:16726} Bolder'ok
	["{quest:95420}: for {npc:255829} in {area:16726}"] = "{quest:95420}: {area:16726} kasabasındaki {npc:255829} için",

	-- Step 50: WANTED: Scoutmaster Vargas
	-- {npc:260211} Scoutmaster Vargas · {npc:256728} Na'zok · {npc:258031} Neza Bloodsnout
	["{npc:260211} is an elite (level 42) at the Alliance scouts' camp in the hills south-east of {npc:256728}, where you go next: grouping up is advised. The poster hangs in the middle of the fort; {npc:258031} takes the eye, later in this guide."] = "{npc:260211}, sıradaki durağın {npc:256728} kampının güneydoğusundaki tepelerde bulunan Alliance izci kampında bir elit (42. seviye): grup kurman tavsiye edilir. İlan kalenin ortasında asılı; gözü bu rehberde daha sonra {npc:258031} teslim alır.",
	-- {object:707249} Wanted (no name in this language: may be words)
	["the {object:707249} poster"] = "{object:707249} ilanı",

	-- Step 51: Na'zok's camp
	-- {npc:256728} Na'zok
	["{npc:256728}'s camp"] = "{npc:256728} adlı NPC'nin kampı",
	-- {area:16743} Rog'mar · {npc:256728} Na'zok
	["North-east from {area:16743} up into the hills: {npc:256728} watches the Paletusk boars from his camp."] = "{area:16743} kalesinden kuzeydoğuya, tepelere çık: {npc:256728} kampından Paletusk yaban domuzlarını gözlüyor.",

	-- Step 52: Bolder'ok
	-- {area:16726} Bolder'ok · {npc:255829} Clugfist
	["North-west to {area:16726}, the ogres' town. {npc:255829}, its chieftain, sits on the hill. The ogres are friendly while you leave them alone."] = "Kuzeybatıya, ogre kasabasına, {area:16726} içine git. Şefi {npc:255829} tepede oturuyor. Ogre'ler sen onlara dokunmadıkça dosttur.",

	-- Step 53: The Twilight ogres' camp
	["The Twilight ogres' camp"] = "Twilight ogre'lerinin kampı",
	-- {npc:256728} Na'zok · {npc:260973} Klunk · {item:269257} Skullbasher · {npc:260211} Scoutmaster Vargas
	-- plural, as words: Twilight Maulers = {npc:260968} Twilight Mauler · Farholde Ambushers = {npc:260023} Farholde Ambusher
	["The Twilight Maulers and Firecallers camp on the ridge east of {npc:256728}. {npc:260973}, who carries the {item:269257}, stands among them. Just south of the ogres, {npc:260211} (an Alliance elite, level 42) and his Farholde Ambushers hold the scouts' camp: keep north of it unless you came with a group for him."] = "Twilight Mauler ve Firecaller'lar {npc:256728} kampının doğusundaki sırtta kamp kurmuş. {item:269257} eşyasını taşıyan {npc:260973} aralarında duruyor. Ogre'lerin hemen güneyinde {npc:260211} (bir Alliance eliti, 42. seviye) ve Farholde Ambusher yaratıkları izci kampını tutuyor: onun için bir grupla gelmediysen kampın kuzeyinde kal.",
	-- {item:269257} Skullbasher · {npc:260973} Klunk
	["{item:269257}, from {npc:260973}"] = "{item:269257}, kaynak: {npc:260973}",

	-- Step 55: The paletusks
	["The paletusks"] = "Paletusk'lar",
	-- {npc:256728} Na'zok
	-- plural, as words: Young Paletusks = {npc:258331} Young Paletusk · Mature Paletusks = {npc:255851} Mature Paletusk
	["South down the hills, round the west side of the Alliance scouts' camp: tap the Young Paletusks with {npc:256728}'s staff to send them home; the Mature Paletusks around the hills drop the boar meat."] = "Tepelerden güneye, Alliance izci kampının batı yakasından dolaşarak in: Young Paletusk yaratıklarına {npc:256728} adlı NPC'nin asasıyla dokunup onları eve yolla; tepelerin çevresindeki Mature Paletusk yaratıkları yaban domuzu eti düşürür.",
	-- {item:268521} Swineherd's Staff
	-- plural, as words: Young Paletusks = {npc:258331} Young Paletusk
	["{item:268521}, on the Young Paletusks"] = "{item:268521}, Young Paletusk yaratıklarında",
	-- {item:769} Chunk of Boar Meat
	-- plural, as words: Mature Paletusks = {npc:255851} Mature Paletusk
	["{item:769}, from the Mature Paletusks"] = "{item:769}, Mature Paletusk yaratıklarından",

	-- Step 57: Jom-jom's Escape
	-- {npc:258048} Jom-jom · {npc:256728} Na'zok · {area:16726} Bolder'ok
	["{npc:258048} waits by the Twilight ogres' camp north-east of {npc:256728}: take him home to {area:16726} and keep the cultists off him. If he falls, take the quest from him again."] = "{npc:258048}, {npc:256728} kampının kuzeydoğusundaki Twilight ogre kampının yanında bekliyor: onu evine, {area:16726} kasabasına götür ve tarikatçıları ondan uzak tut. Düşerse görevi ondan yeniden al.",
	-- {npc:258048} Jom-jom · {area:16726} Bolder'ok
	["help {npc:258048} reach {area:16726}"] = "{npc:258048} adlı NPC'nin {area:16726} kasabasına ulaşmasına yardım et",

	-- Step 58: Bolder'ok
	-- {npc:255829} Clugfist · {npc:257062} Jezap Jinglesprocket · {quest:94668} Bloodmaster's Ring
	["Back to {npc:255829} on his hill. {npc:257062} runs the {quest:94668} just below it."] = "Tepesindeki {npc:255829} yanına dön. {npc:257062}, hemen aşağısında {quest:94668} arenasını işletiyor.",

	-- Step 59: Clugfist
	-- {quest:95428} Clugfist's Decree · {npc:256418} Krom'rosh · {area:16743} Rog'mar
	["{quest:95428}: for {npc:256418} in {area:16743}, later in this guide"] = "{quest:95428}: bu rehberde daha sonra {area:16743} kalesindeki {npc:256418} için",
	-- {quest:94669} Pay to Play
	["{quest:94669}: the Ring's bouts, one-on-one fights with elites (41-45); a deposit first"] = "{quest:94669}: Ring'in maçları, elitlerle (41-45) bire bir dövüşler; önce bir depozito",

	-- Step 60: The Bloodmaster's Ring: Buzzbeak
	-- {quest:94670} Bloodmaster's Ring
	["The {quest:94670}: Buzzbeak"] = "{quest:94670}: Buzzbeak",
	-- {npc:255829} Clugfist · {npc:258626} Mog'thar · {npc:257059} Chub'chob · {npc:257062} Jezap Jinglesprocket
	["Each bout is a fight in the ring below {npc:255829}'s hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) and {npc:257059} (45). Come in rested, with full health and mana; if a bout goes wrong, {npc:257062} offers it again."] = "Her maç, {npc:255829} adlı NPC'nin tepesinin altındaki arenada bir elite karşı bir dövüş: Buzzbeak (41), Kronk ve Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) ve {npc:257059} (45). Dinlenmiş olarak, tam can ve manayla gir; bir maç kötü giderse {npc:257062} onu yeniden verir.",
	-- {quest:94670} Bloodmaster's Ring
	["{quest:94670}: Buzzbeak"] = "{quest:94670}: Buzzbeak",
	["beat Buzzbeak"] = "Buzzbeak'i yen",

	-- Step 61: The Bloodmaster's Ring: Kronk and Bonegnaw
	-- {quest:94670} Bloodmaster's Ring
	["The {quest:94670}: Kronk and Bonegnaw"] = "{quest:94670}: Kronk ve Bonegnaw",
	["Kronk"] = "Kronk",
	["Bonegnaw"] = "Bonegnaw",

	-- Step 62: The Bloodmaster's Ring: Mog'thar
