	-- Step 63: The Bloodmaster's Ring: Snufflesnout and Chub'chob
	-- {quest:94964} Bloodmaster's Ring · {npc:257059} Chub'chob
	["The {quest:94964}: Snufflesnout and {npc:257059}"] = "{quest:94964}: Snufflesnout ve {npc:257059}",
	-- {npc:257062} Jezap Jinglesprocket · {npc:258626} Mog'thar
	["{npc:257062} offers the last two once Gobam's errands are done (players' recordings), which this guide leaves out. They are level 44 and 45: leave them for later if {npc:258626} was a close fight."] = "{npc:257062} son ikisini, bu rehberin dışarıda bıraktığı Gobam'ın işleri bitince verir (oyuncu kayıtları). 44 ve 45. seviyeler: {npc:258626} zor bir dövüştüyse onları sonraya bırak.",
	["Snufflesnout (44)"] = "Snufflesnout (44)",
	-- {npc:255829} Clugfist
	["{npc:255829}, on the hill"] = "{npc:255829}, tepede",

	-- Step 64: Powderfuse Port
	-- {area:16727} Powderfuse Port · {npc:255897} Friz Frazzlespark · {npc:259962} Fimbo Greasemitz · {npc:259961} Wharfmaster Whizzbuzz
	["South-east down out of the hills to {area:16727}, the goblins' harbour on the coast. {npc:255897} keeps a stall at the west end of the docks, {npc:259962} cooks by the inn, and {npc:259961} works the north pier."] = "Tepelerden güneydoğuya, kıyıdaki goblin limanına, {area:16727} içine in. {npc:255897} iskelelerin batı ucunda bir tezgâh işletiyor, {npc:259962} hanın yanında yemek pişiriyor, {npc:259961} de kuzey iskelede çalışıyor.",
	-- {object:628948} WANTED! (no name in this language: may be words) · {npc:260235} Trapclaw
	["The {object:628948} poster by the inn: {npc:260235}"] = "Hanın yanındaki {object:628948} ilanı: {npc:260235}",

	-- Step 65: Wharfmaster Whizzbuzz
	-- {npc:259961} Wharfmaster Whizzbuzz · {item:277974} Twice Reordered Package
	["{npc:259961} on the north pier takes Lozgil's {item:277974}."] = "Kuzey iskeledeki {npc:259961}, Lozgil'in {item:277974} paketini teslim alır.",

	-- Step 66: WANTED: Old Rot-Chum
	-- {npc:257001} Old Rot-Chum
	["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001}, güney kıyısında elit bir yaratık (seviye 42): grup kurman önerilir.",
	-- {object:628948} WANTED! (no name in this language: may be words)
	["The {object:628948} poster by the inn"] = "Hanın yanındaki {object:628948} ilanı",

	-- Step 67: The murlocs, south-west
	["The murlocs, south-west"] = "Murloclar, güneybatıda",
	-- {quest:95260} Terrors From the Deep · {npc:260231} Argo Brinewhistle
	["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "Limandan kıyı boyunca güneybatıya: tuzlu su murlocları kumsallarda kamp kurmuş. Yolda patikanın yanında boyalı bir post gerili: iskelelerdeki {npc:260231} için {quest:95260} görevini başlatır.",

	-- Step 69: Back through the port
	["Back through the port"] = "Limandan geri geç",
	["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Kıyı boyunca kuzeye dön: crawler'lara giderken iskelelerde murlocları ve postu teslim et.",
	-- {quest:95261} It Takes Guts
	["{quest:95261}: the beasts' entrails come as you go; the mushrooms grow on the ridge west of the pirates"] = "{quest:95261}: hayvanların bağırsakları yolda gelir; mantarlar korsanların batısındaki sırtta büyüyor",

	-- Step 70: Beast Entrails as you go
	-- {item:268632} Beast Entrails
	["{item:268632} as you go"] = "Yol boyunca {item:268632}",
	-- {zone:2548} Riverglades · {item:268632} Beast Entrails · {npc:260231} Argo Brinewhistle · {npc:257001} Old Rot-Chum · {npc:263380} Ghostmaw
	["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42) wanders the shore and {npc:263380} (elite, 42) the river: take your beasts away from them."] = "{zone:2548} bölgesindeki çoğu hayvan {npc:260231} için {item:268632} düşürür: bu kıyıdaki kıyı sürüngenleri ve korsanların batısındaki sırttaki yaban domuzları.\nDikkat: {npc:257001} (elit, 42) kıyıda, {npc:263380} (elit, 42) nehirde dolaşıyor: hayvanlarını onlardan uzakta avla.",

	-- Step 71: The crawlers and Trapclaw
	-- {npc:260235} Trapclaw
	["The crawlers and {npc:260235}"] = "Crawler'lar ve {npc:260235}",
	-- {npc:259962} Fimbo Greasemitz · {npc:260231} Argo Brinewhistle · {npc:260235} Trapclaw · {npc:259758} Gul'gash
	["North along the beach from the docks: the crawlers drop the meat for {npc:259962}, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "İskelelerden kumsal boyunca kuzeye: kıyı sürüngenleri {npc:259962} için et düşürür, bağırsakları da {npc:260231} için sayılır. Büyük bir yengeç olan {npc:260235}, iskelelerin doğusundaki kayalarda koşturuyor. 49. seviye rare elit {npc:259758} bu kıyıda iskelelerden korsan kampına kadar dolaşıyor: görürsen ondan epey uzak dur.",

	-- Step 72: The Eastsea pirates
	["The Eastsea pirates"] = "Eastsea korsanları",
	-- {npc:259758} Gul'gash
	["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "Kıyı boyunca kuzeydoğuya, kayalıklardaki korsan kampına git. Buccaneer ve Musketeer'lar kaçak malları taşıyor. {npc:259758} de kampta dolaşıyor: ona göz kulak ol.",

	-- Step 73: Powderfuse Port
	["Back to the port, from the north pier west through the docks."] = "Limana dön: kuzey iskeleden batıya, iskelelerin içinden.",
	-- {quest:95293} Smuggler's Special · {npc:260390} Captain Bentcoin
	["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293}: korsanların kampındaki {npc:260390} için",

	-- Step 75: The pirates' second wave
	["The pirates' second wave"] = "Korsanların ikinci dalgası",
	-- {npc:259758} Gul'gash
	-- plural, as words: Eastsea Raiders = {npc:257915} Eastsea Raider
	["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. Watch for {npc:259758} on these cliffs.\nCareful: the Eastsea Raiders are level 44-45, a level or two over you here: pull them one at a time from the edge of the slopes and keep clear of the camp behind them."] = "Limandan kıyı boyunca kuzeye: Eastsea yağmacıları ve bombacıları korsan kampının batısındaki yamaçlarda barut fıçılarının arasında mevzilenmiş. Bu uçurumlarda {npc:259758} yaratığını gözle.\nDikkat: Eastsea Raider yaratıkları 44-45. seviye, burada senden bir-iki seviye yüksek: yamaçların kenarından tek tek çek ve arkalarındaki kamptan uzak dur.",

	-- Step 76: Captain Bentcoin
	-- {npc:260390} Captain Bentcoin · {npc:260391} Captain Haynes
	["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Kayalıklar boyunca doğuya, korsan kampının en ucuna: {npc:260390} suyun kenarında bekliyor, {npc:260391} de yanında.",

	-- Step 77: Powderfuse Port
	["Back to the port."] = "Limana dön.",
	-- {npc:255897} Friz Frazzlespark · {quest:95296} Shipping and Handling · {npc:260405} Wharfmaster Steamfizzle · {area:977} Steamwheedle Port · {zone:1444} Feralas · {zone:1446} Tanaris
	["{npc:255897}: {quest:95296}, for {npc:260405} at {area:977} in the {zone:1444} & {zone:1446} guide"] = "{npc:255897}: {quest:95296}, {zone:1444} ve {zone:1446} rehberinde {area:977} limanındaki {npc:260405} için",

	-- Step 78: The pirates' ships
	["The pirates' ships"] = "Korsan gemileri",
	-- {quest:95124} Admiral Lamora · {npc:259758} Gul'gash
	["Out to the pirates' cliffs once more. Plant Whizzbuzz's charges on the three ships moored below the camp, south to north; {quest:95124} stands by the middle one, with her loot chest beside her. Keep an eye out for {npc:259758} on the way.\nCareful: {quest:95124} is level 45, a level or two over you here: clear the deck around her first and come in with full health."] = "Bir kez daha korsanların uçurumlarına çık. Whizzbuzz'ın patlayıcılarını kampın aşağısında demirli üç gemiye güneyden kuzeye yerleştir; {quest:95124} ortadakinin yanında, ganimet sandığı yanında duruyor. Yolda {npc:259758} yaratığına göz kulak ol.\nDikkat: {quest:95124} 45. seviye, burada senden bir-iki seviye yüksek: önce çevresindeki güverteyi temizle ve tam canla gir.",
	-- {item:268505} Remote Explosive Charge
	["{item:268505}, the southern ship"] = "{item:268505}, güneydeki gemi",
	["the middle ship"] = "ortadaki gemi",
	["the northern ship"] = "kuzeydeki gemi",

	-- Step 79: Rotflesh Mushrooms
	-- plural, as words: Rotflesh Mushrooms = {item:268664} Rotflesh Mushroom
	["Rotflesh Mushrooms"] = "Rotflesh Mushroom mantarları",
	-- plural, as words: Rotflesh Mushrooms = {item:268664} Rotflesh Mushroom · Mature Paletusks = {npc:255851} Mature Paletusk
	["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "Kuzeydeki gemiden batıya, sırta çık: Rotflesh Mushroom mantarları kayaların arasında, Twilight ogre'larının kampına yakın yetişiyor. Sırttaki Mature Paletusk yaratıkları da bağırsak verir.",

	-- Step 80: Finish the Beast Entrails
	-- {item:268632} Beast Entrails
	["Finish the {item:268632}"] = "{item:268632} işini bitir",
	-- {npc:259758} Gul'gash
	["South-east back towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "Güneydoğuya, limana doğru dön: iskelelerin kuzeyindeki kumsaldaki kıyı sürüngenleri en hızlı bağırsak kaynağı. {npc:259758} bu kumsala da iner.",

	-- Step 81: Powderfuse Port
	["Down to the port."] = "Limana in.",
	-- {quest:95267} The Monster Surfaces · {npc:257001} Old Rot-Chum
	["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267}: limanın güneybatısındaki sığlıklarda, elit {npc:257001} yakınında büyük bir hayvan",

	-- Step 82: The Monster Surfaces
	-- {npc:260244} Monstrous Threshadon · {npc:257001} Old Rot-Chum
	["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "{npc:260244}, limanın güneybatısındaki sığlıklarda, murloc kumsallarının aşağısında dolaşıyor. Elit {npc:257001} yakında kıyıda yürüyor: ona yol ver.",

	-- Step 84: Rog'mar
	-- {area:16743} Rog'mar · {npc:256418} Krom'rosh · {npc:255829} Clugfist · {npc:258570} Da'grosh
	["Back to {area:16743} from the port, where your Hearthstone is set. {npc:256418} in the middle of the fort: {npc:255829}'s word sends him looking for {npc:258570}, his warrior in the west."] = "Limandan Hearthstone'unun bağlı olduğu {area:16743} kalesine dön. Kalenin ortasındaki {npc:256418}: {npc:255829} adlı NPC'nin haberi onu batıdaki savaşçısı {npc:258570} arayışına yollar.",
	-- {quest:94744} The Wayward Warrior · {npc:258570} Da'grosh · {area:16723} Sunnyglade
	["{quest:94744}: for {npc:258570}, west of {area:16723}"] = "{quest:94744}: {area:16723} köyünün batısındaki {npc:258570} için",

	-- Step 86: Da'grosh
	-- {area:16743} Rog'mar · {area:16723} Sunnyglade · {area:16685} Twilight's Shroud · {npc:258570} Da'grosh · {npc:256418} Krom'rosh
	["West from {area:16743} through {area:16723} and on up the valley towards {area:16685}: {npc:258570}, {npc:256418}'s wayward warrior, keeps a camp in the hills below the Twilight cult's fortress."] = "{area:16743} kalesinden batıya, {area:16723} köyünün içinden geçip vadiden {area:16685} yönüne çık: {npc:256418} adlı NPC'nin yolunu kaybetmiş savaşçısı {npc:258570}, Twilight tarikatının kalesinin aşağısındaki tepelerde kamp kurmuş.",

	-- Step 87: Crag'rog
	-- {npc:260993} Crag'rog · {area:16726} Bolder'ok · {npc:258570} Da'grosh
	["{npc:260993}, a {area:16726} ogre, hides in the cave west of {npc:258570}'s camp."] = "Bir {area:16726} ogre'si olan {npc:260993}, {npc:258570} kampının batısındaki mağarada saklanıyor.",

	-- Step 88: The Twilight camps
	["The Twilight camps"] = "Twilight kampları",
	-- {npc:258570} Da'grosh · {npc:256881} Overlord Kilgar · {npc:256891} Executioner Morg · {npc:258023} Sergeant Riftan
	-- plural, as words: Rog'mar Scouts = {npc:257450} Rog'mar Scout · Twilight Enforcers = {npc:256800} Twilight Enforcer · Farholde Lookouts = {npc:258686} Farholde Lookout
	["The cult's camps fill the valley south and west of {npc:258570}. Free the captive Rog'mar Scouts as you find them. Twilight Enforcers (elites, level 45) patrol through the camps: watch where they walk before each pull. {npc:256881} and {npc:256891} (elites, 46) hold the fortress at the valley's head: pull the cultists away from them. {npc:258023}'s Alliance camp sits at the valley's south end, and its Farholde Lookouts (level 46) attack the Horde: stay north of it."] = "Tarikatın kampları {npc:258570} kampının güneyindeki ve batısındaki vadiyi dolduruyor. Esir Rog'mar Scout'ları buldukça serbest bırak. Twilight Enforcer yaratıkları (elit, 45. seviye) kamplar arasında devriye geziyor: her çekişten önce nereden yürüdüklerine bak. {npc:256881} ve {npc:256891} (elit, 46) vadinin başındaki kaleyi tutuyor: tarikatçıları onlardan uzağa çek. {npc:258023} adlı NPC'nin Alliance kampı vadinin güney ucunda, Farholde Lookout yaratıkları (46. seviye) da Horde'a saldırır: kampın kuzeyinde kal.",
	-- plural, as words: Rog'mar Scouts = {npc:257450} Rog'mar Scout
	["free five captive Rog'mar Scouts"] = "beş esir Rog'mar Scout'u serbest bırak",

	-- Step 89: The ogre mine
	["The ogre mine"] = "Ogre madeni",
	-- plural, as words: Twilight Enforcers = {npc:256800} Twilight Enforcer
	["North of the camps the cult works ogre miners in a mine: talk five of them into rising up against their masters.\nCareful: Twilight Enforcers (elites, level 45) walk past the mine's mouth on their way through the camps. Wait for one to pass before you go in."] = "Kampların kuzeyinde tarikat bir madende ogre madencileri çalıştırıyor: beşini efendilerine karşı ayaklanmaya ikna et.\nDikkat: Twilight Enforcer yaratıkları (elit, 45. seviye) kamplardan geçerken maden ağzının önünden yürür. İçeri girmeden önce birinin geçmesini bekle.",
	-- plural, as words: Ogre Miners = {npc:260995} Ogre Miner
	["recruit five Ogre Miners"] = "beş Ogre Miner kazan",

	-- Step 92: Bring Me His Head
	-- {npc:256881} Overlord Kilgar
	["{npc:256881} is an elite (level 46) in the fortress at the head of the valley, with the Enforcers around him: grouping up is advised."] = "{npc:256881}, vadinin başındaki kalede, çevresinde Enforcer'larla elit bir yaratık (seviye 46): grup kurman önerilir.",

	-- Step 93: Twilight's Shroud
	-- {area:340} Kargath · {area:3} Badlands · {npc:258570} Da'grosh · {area:16685} Twilight's Shroud
	["The next guide flies from {area:340} in the {area:3}: north out of {npc:258570}'s valley and up through {area:16685}, the way through to the {area:3}."] = "Sonraki rehber {area:3} bölgesindeki {area:340} kalesinden uçar: {npc:258570} vadisinden kuzeye çık ve {area:3} bölgesine geçit veren {area:16685} içinden yukarı tırman.",

	-- Step 94: Kargath
	-- {area:3} Badlands · {area:340} Kargath
	["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "{area:3} bölgesini geçip bölgenin batı kenarında uçurumlara oyulmuş Horde kalesine, {area:340} içine git: uçuş ustası kalenin eteğinde duruyor.",
